const ELEMENT_PROP_KEYS = new Set(["theme","fontWeight","lag","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  fontWeight: 500,
  lag: 14,
  fontFamily: "Epilogue",
  scale: 1,
  delay: 0,
  speed: 1,
};

type EditRippleElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof EditRippleBase>;

const EditRippleInner = forwardRef<
  HTMLDivElement,
  EditRippleElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<EditRipple>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <EditRippleBase
          {...(componentProps as unknown as ComponentProps<typeof EditRippleBase>)}
        />
      </div>
    </Sequence>
  );
});

export const EditRipple = Interactive.withSchema({
  Component: EditRippleInner,
  componentName: "<EditRipple>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
